// Generated by Parity. Serves the rebuilt app on 127.0.0.1 and a small JSON store backed by SQLite.
import { Database } from "bun:sqlite";
import { join } from "node:path";

const port = Number(process.env.PORT ?? 0);
const db = new Database(process.env.APP_DB ?? ":memory:", { strict: true });
db.exec(
  "CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, body TEXT NOT NULL)",
);
const publicDir = join(import.meta.dir, "public");

const server = Bun.serve({
  hostname: "127.0.0.1",
  port,
  async fetch(req) {
    const url = new URL(req.url);
    if (url.pathname.startsWith("/api/records/")) {
      const kind = url.pathname.slice("/api/records/".length);
      if (!/^[a-z0-9-]{1,40}$/.test(kind)) return new Response("bad kind", { status: 400 });
      if (req.method === "POST") {
        const body = await req.text();
        if (body.length > 100_000) return new Response("too large", { status: 413 });
        const row = db.query("INSERT INTO records (kind, body) VALUES (?, ?) RETURNING id").get(kind, body);
        return Response.json(row);
      }
      const rows = db.query("SELECT id, body FROM records WHERE kind = ? ORDER BY id").all(kind);
      return Response.json(rows);
    }
    const path = url.pathname === "/" ? "/index.html" : url.pathname;
    if (path.includes("..")) return new Response("not found", { status: 404 });
    const file = Bun.file(join(publicDir, path));
    return (await file.exists()) ? new Response(file) : new Response("not found", { status: 404 });
  },
});
console.log(`listening on http://127.0.0.1:${server.port}`);
